import fs from 'node:fs/promises';
import path from 'node:path';

const root = process.cwd();
const migrationsDir = path.join(root, 'supabase', 'migrations');
const outputDir = path.join(root, 'work');
const outputFile = path.join(outputDir, 'detailflow-setup.sql');

const migrationFiles = (await fs.readdir(migrationsDir))
  .filter((file) => file.endsWith('.sql'))
  .sort();

if (migrationFiles.length === 0) {
  throw new Error('No SQL migrations found in supabase/migrations');
}

const migrationSources = await Promise.all(
  migrationFiles.map(async (file) => ({
    file,
    source: await fs.readFile(path.join(migrationsDir, file), 'utf8'),
  })),
);

const unsafeFixturePattern = /insert\s+into\s+(?:auth\.users|public\.admin_members)\b/i;
for (const { file, source } of migrationSources) {
  if (unsafeFixturePattern.test(source)) {
    throw new Error(`Refusing to bundle Auth/admin fixture writes from migration ${file}`);
  }
}

const versions = migrationFiles.map((file) => file.split('_', 1)[0]);
const sections = migrationSources.map(
  ({ file, source }) => `-- supabase/migrations/${file}\n\n${source.trim()}\n`,
);
const header = [
  '-- DetailFlow SQL Editor installation bundle',
  '-- Generated by npm run prepare:database from committed migrations in filename order.',
  '-- Run this once in a new, empty Supabase project SQL Editor.',
  '-- It creates schema, RLS, triggers, RPCs, and the project service definitions only.',
  '-- It does not create Auth users, admin memberships, demo appointments, passwords,',
  '-- or CLI migration-history rows.',
  '--',
  `-- Included migration versions: ${versions.join(', ')}`,
  '-- After this transaction succeeds, use the CLI migration repair commands in README.md',
  '-- before running supabase db push against this project.',
  '',
  'begin;',
  '',
].join('\n');
const bundle = `${header}${sections.join('\n')}\ncommit;\n`;

await fs.mkdir(outputDir, { recursive: true });
await fs.writeFile(outputFile, bundle, 'utf8');
console.log(`Prepared ${path.relative(root, outputFile)} from ${migrationFiles.length} migrations: ${versions.join(', ')}`);
